/* Module: common/uplink_config */
unsigned clamp_nprach_repetitions(unsigned requested)
{
    if (requested < 1u) return 1u;
    if (requested > 8u) return 8u;
    return requested;
}

/* Module: rrc/connection_setup */
void encode_nprach_config(struct rrc_config *out, unsigned repetitions)
{
    out->nprach_repetitions = clamp_nprach_repetitions(repetitions);
}

/* Module: mac/uplink_scheduler */
void build_ul_grant(struct ul_grant *grant, unsigned repetitions)
{
    grant->npusch_repetitions = clamp_nprach_repetitions(repetitions);
}

void prepare_access_resources(struct rrc_config *rrc, struct ul_grant *grant, unsigned repetitions)
{
    encode_nprach_config(rrc, repetitions);
    build_ul_grant(grant, repetitions);
}

