/* Module: phy/rsrp_filter */
struct rsrp_filter { int value_q4; int initialized; };

void rsrp_filter_update(struct rsrp_filter *filter, int sample_q4)
{
    if (!filter->initialized) {
        filter->value_q4 = sample_q4;
        filter->initialized = 1;
        return;
    }
    filter->value_q4 += (sample_q4 - filter->value_q4) / 4;
}

/* Module: rrc/measurement_reporting */
int measurement_report_rsrp(const struct rsrp_filter *filter)
{
    return filter->value_q4;
}

void process_measurement_sample(struct rsrp_filter *filter, int sample_q4, struct rrc_report *report)
{
    rsrp_filter_update(filter, sample_q4);
    report->rsrp_q4 = measurement_report_rsrp(filter);
}

/* Module: mac/link_adaptation */
int select_mcs_from_rsrp(int rsrp_q4)
{
    if (rsrp_q4 < -440) return 0;
    if (rsrp_q4 < -360) return 1;
    return 2;
}

void schedule_uplink(struct rsrp_filter *filter, int sample_q4, struct ul_grant *grant)
{
    rsrp_filter_update(filter, sample_q4);
    grant->mcs = select_mcs_from_rsrp(filter->value_q4);
}

