/* Module: core/timer */
#define TIMER_TICKS_PER_SECOND 100u

unsigned timer_ms_to_ticks(unsigned milliseconds)
{
    return (milliseconds * TIMER_TICKS_PER_SECOND) / 1000u;
}

void timer_start(struct timer *timer, unsigned milliseconds)
{
    timer->remaining_ticks = timer_ms_to_ticks(milliseconds);
    timer->active = 1;
}

/* Module: nas/attach */
void start_attach_guard(struct nas_context *ctx)
{
    timer_start(&ctx->attach_guard, ctx->attach_guard_ms);
}

/* Module: rrc/connection_recovery */
void start_reestablishment_wait(struct rrc_context *ctx)
{
    timer_start(&ctx->reestablishment_wait, ctx->reestablishment_wait_ms);
}

/* Module: mac/harq */
void start_harq_feedback_timer(struct harq_process *process, unsigned timeout_ms)
{
    timer_start(&process->feedback_timer, timeout_ms);
}

